		@JsonTypeInfo(use = JsonTypeInfo.Id.NAME, property = "type")
		// @formatter:off
		@JsonSubTypes({
				@JsonSubTypes.Type(value = ImageUrlChunk.class, name = "image_url"),
				@JsonSubTypes.Type(value = ReferenceChunk.class, name = "reference"),
