						this.defaultOptions.isGitHubModels(), this.defaultOptions.getModel(),
						this.defaultOptions.getTimeout(), this.defaultOptions.getMaxRetries(),
						this.defaultOptions.getProxy(), this.defaultOptions.getCustomHeaders()));
