	private OpenAiSdkAudioSpeechOptions merge(OpenAiSdkAudioSpeechOptions source, OpenAiSdkAudioSpeechOptions target) {
		OpenAiSdkAudioSpeechOptions.Builder builder = OpenAiSdkAudioSpeechOptions.builder();

