		 * Default constructor with default options.
		 */
		private Builder() {
			this.defaultOptions = OpenAiSdkAudioSpeechOptions.builder()
				.model(DEFAULT_MODEL_NAME)
				.voice(OpenAiSdkAudioSpeechOptions.Voice.ALLOY)
