+	static List<McpSchema.Content> parseContentList(String callResult) {
+		try {
+			JsonNode jsonNode = OBJECT_MAPPER.readTree(callResult);
+			if (jsonNode.isArray() && !jsonNode.isEmpty()) {
+				List<McpSchema.Content> contents = new ArrayList<>();
