+	/**
+	 * Comparison types for filter operations.
+	 */
+	private enum ComparisonOp {
+
+		/** Equals comparison. */
+		EQ,
+		/** Not equals comparison. */
+		NE,
+		/** Greater than comparison. */
+		GT,
+		/** Greater than or equals comparison. */
+		GTE,
+		/** Less than comparison. */
